program.compute:
options = read('/input/options')
ids = []
for option in options:
    ids = ids + [option['id']]
result = []
for count in range(goal['min_count'], goal['max_count'] + 1):
    for selection in combinations(ids, count):
        candidate = list(selection)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

program.effects:
artifact = read('/output/selection')
if artifact:
    if not valid(artifact):
        status('report')
    else:
        result = artifact
        delivery = receipt('report')
        if delivery == 'success':
            sent = True
        else:
            if delivery == 'unknown':
                sent_status = status('report')
            sent = sent_status == 'sent'
            if not sent and delivery != 'unknown':
                send('report', 'team', result)
else:
    if not result or not valid(result):
        status('report')
    else:
        write('/output/selection', result)
        delivery = receipt('report')
        sent_status = 'not_sent'
        if delivery == 'unknown':
            sent_status = status('report')
        if delivery != 'success' and sent_status != 'sent' and delivery != 'unknown':
            send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
if exists('/output/selection'):
    final_selection = read('/output/selection')
    final_valid = valid(final_selection)
    final_receipt = receipt('report')
    if final_valid and final_receipt == 'success':
        status('report')
    elif final_valid and final_receipt == 'unknown':
        status('report')
    else:
        status('report')
else:
    status('report')

